WITH remaining_keys AS (SELECT browser, device FROM sessions EXCEPT ALL SELECT browser, device FROM sessions WHERE country IN ('UK', 'SG')), verified AS (SELECT s.* FROM sessions s INNER JOIN remaining_keys k ON s.browser = k.browser AND s.device = k.device) SELECT DATE_TRUNC('WEEK', started_at) AS week_start, MAX(started_at) AS last_seen, MAX(started_at) AS last_seen_2 FROM verified GROUP BY week_start ORDER BY week_start DESC NULLS FIRST;
